# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KELAM İLMİNDE BİLGİNİN TANIMI VE TÜRLERİ (KADÎM VE HÂDİS BİLGİ)</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Kadîm Bilgi (İlahi İlim)</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">• Yüce Allah\'ın (el-Alîm) ezeli ve ebedi bilgisidir.</text>\n  <text x="42" y="118" font-size="11.5" fill="#1e3a8a">• Zaman, mekân ve araçla sınırlı değildir.</text>\n  <text x="42" y="140" font-size="11.5" fill="#1e3a8a">• Artma, eksilme, unutma veya yanılma olmaz.</text>\n  <text x="42" y="162" font-size="11.5" fill="#1e3a8a">• Olmuş, olan ve olacak her şeyi kuşatır.</text>\n  <rect x="42" y="182" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="201" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Mutlak, sınırsız ve başlangıçsız bilgi</text>\n  <text x="182" y="218" text-anchor="middle" font-size="10.5" fill="#1e3a8a">(Allah\'ın sübûtî sıfatlarından "İlim")</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. Hâdis Bilgi (Yaratılmışların Bilgisi)</text>\n  <text x="378" y="96" font-size="11.5" fill="#14532d">• İnsan, melek ve cinlerin sonradan oluşan</text>\n  <text x="386" y="112" font-size="11.5" fill="#14532d">sınırlı bilgisidir (Kسب / öğrenme yoluyla).</text>\n  <rect x="378" y="126" width="280" height="46" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="144" font-size="11" font-weight="bold" fill="#15803d">a) Zaruri (Zorunlu / Bedîhî) Bilgi:</text>\n  <text x="388" y="160" font-size="10.5" fill="#14532d">Düşünme ve delil gerektirmeden oluşan (bütün &gt; parça).</text>\n  <rect x="378" y="180" width="280" height="46" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="198" font-size="11" font-weight="bold" fill="#15803d">b) İstidlali (Kesbî / Nazarî) Bilgi:</text>\n  <text x="388" y="214" font-size="10.5" fill="#14532d">Akıl yürütme, gözlem ve delille ulaşılan bilgi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM KELAMINDA DOĞRU BİLGİNİN ÜÇ TEMEL KAYNAĞI</text>\n  <rect x="22" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. Akl-ı Selim (Selim Akıl)</text>\n  <text x="34" y="96" font-size="10.5" fill="#78350f">• Önyargı, taklit ve tutkudan</text>\n  <text x="42" y="110" font-size="10.5" fill="#78350f">arınmış sağlıklı düşünen akıl.</text>\n  <text x="34" y="132" font-size="10.5" fill="#78350f">• Dini sorumluluğun (teklif)</text>\n  <text x="42" y="146" font-size="10.5" fill="#78350f">ve imanın temel şartıdır.</text>\n  <text x="34" y="168" font-size="10.5" fill="#78350f">• Eserden müessire (evrenden</text>\n  <text x="42" y="182" font-size="10.5" fill="#78350f">Yaratıcı\'ya) istidlal yapar.</text>\n  <rect x="34" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="127" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Sahih nakil ile akıl çelişmez!</text>\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">2. Haber-i Sâdık (Doğru Haber)</text>\n  <text x="257" y="96" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">a) Mütevatir Haber:</tspan> Yalan</text>\n  <text x="265" y="110" font-size="10.5" fill="#581c87">üzerine birleşmesi imkânsız</text>\n  <text x="265" y="124" font-size="10.5" fill="#581c87">topluluğun aktardığı haber.</text>\n  <text x="257" y="146" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">b) Peygamber Haberi:</tspan></text>\n  <text x="265" y="160" font-size="10.5" fill="#581c87">Mucize ile desteklenen elçinin</text>\n  <text x="265" y="174" font-size="10.5" fill="#581c87">vahye dayalı bildirdiği haber.</text>\n  <rect x="257" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Gayb ve ibadet bilgisinin kaynağı</text>\n  <rect x="468" y="48" width="210" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="573" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">3. Havâss-ı Selîme (Duyular)</text>\n  <text x="480" y="96" font-size="10.5" fill="#1e3a8a">• Sağlıklı işleyen beş duyu organı</text>\n  <text x="488" y="110" font-size="10.5" fill="#1e3a8a">(görme, işitme, dokunma,</text>\n  <text x="488" y="124" font-size="10.5" fill="#1e3a8a">tatma ve koklama).</text>\n  <text x="480" y="146" font-size="10.5" fill="#1e3a8a">• Dış dünyadaki maddi varlıkları,</text>\n  <text x="488" y="160" font-size="10.5" fill="#1e3a8a">deney ve gözlem verilerini</text>\n  <text x="488" y="174" font-size="10.5" fill="#1e3a8a">akla ulaştırır (Nahl, 78).</text>\n  <rect x="480" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="573" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Deney ve gözlemin temel aracı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİLGİ KAYNAKLARI İLE BAĞLANTILI KAVRAMLAR: DELİL VE HÜKÜM</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Kelamda Delil, Nazar ve İstidlal</text>\n  <text x="40" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Delil (Burhan / Hüccet):</tspan> Bilinmeyen bir</text>\n  <text x="48" y="112" font-size="11" fill="#14532d">gerçeğe ulaşmayı sağlayan sağlam kanıt.</text>\n  <text x="40" y="136" font-size="11" fill="#14532d">• <tspan font-weight="bold">Nazar ve İstidlal:</tspan> Aklın deliller üzerinde</text>\n  <text x="48" y="152" font-size="11" fill="#14532d">düşünerek bilinenden bilinmeyene ulaşması.</text>\n  <text x="40" y="176" font-size="11" fill="#14532d">• <tspan font-weight="bold">Akli Hükümler:</tspan> Vâcip (zorunlu), Mümkün</text>\n  <text x="48" y="192" font-size="11" fill="#14532d">(olabilir) ve Mümteni / Muhal (imkânsız).</text>\n  <rect x="40" y="202" width="285" height="26" rx="5" fill="#ffffff" stroke="#4ade80"/>\n  <text x="182" y="219" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">İsrâ 36: "Hakkında bilgin olmayan şeyin ardına düşme!"</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Kelamda Bağlayıcı Olmayan Yollar</text>\n  <text x="378" y="96" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">İlham, Keşif ve Rüya:</tspan> Kişisel (sübjektif)</text>\n  <text x="386" y="112" font-size="11" fill="#7f1d1d">tecrübelerdir; yanılma ihtimali taşır ve</text>\n  <text x="386" y="128" font-size="11" fill="#7f1d1d">başkaları için dinî delil (hüccet) olmaz.</text>\n  <text x="378" y="152" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Zan, Şüphe ve Vehim:</tspan> Kesinlik taşımayan</text>\n  <text x="386" y="168" font-size="11" fill="#7f1d1d">tahminlerle inanç (akaid) esasları belirlenemez.</text>\n  <rect x="378" y="186" width="280" height="42" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="517" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">İnanç esasları kesin bilgiye (yakîn) dayanır;</text>\n  <text x="517" y="220" text-anchor="middle" font-size="10.5" fill="#7f1d1d">kehanet, fal ve batıl inançlar reddedilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
